// Every mock dataset is generated by its own seeded faker. The data is invented by construction
// (no name, figure or date comes from a real person or an export), it's the same on every load,
// and adding or changing one dataset never shifts another.
//
// Generators use faker's locale-free SimpleFaker, and take names from namePool.js (a sample of
// faker's locale data, made by scripts/generate-name-pool.mjs), so builds stay small.
import { SimpleFaker } from '@faker-js/faker'
import { TODAY } from './clock'
import { NAME_POOL } from './namePool'

// Change this to get a different, equally consistent, set of people and records.
export const DATA_SEED = 4271

function hash(text) {
  let h = 0
  for (const char of text) h = (h * 31 + char.charCodeAt(0)) | 0
  return Math.abs(h)
}

// A faker seeded for one dataset, with dates relative to TODAY.
export function fakerFor(dataset) {
  const faker = new SimpleFaker()
  faker.seed(DATA_SEED + hash(dataset))
  faker.setDefaultRefDate(TODAY.toDate())
  return faker
}

// Nationalities athletes are drawn from, and how often.
export const NATIONALITIES = [
  { country: 'England', weight: 6 },
  { country: 'Ireland', weight: 2 },
  { country: 'Spain', weight: 2 },
  { country: 'France', weight: 2 },
  { country: 'Germany', weight: 1 },
  { country: 'Italy', weight: 1 },
  { country: 'Brazil', weight: 1 },
  { country: 'USA', weight: 1 },
]

// Names for one nationality, drawn with the given faker. sex is 'male' or 'female'.
export function namesFor(faker, country) {
  const pool = NAME_POOL[country]
  const surname = () => faker.helpers.arrayElement(pool.last)
  return {
    firstName: (sex) => faker.helpers.arrayElement(pool[sex]),
    lastName: () => (pool.doubleSurname ? `${surname()} ${surname()}` : surname()),
  }
}
